exports.handler = async (event, context2) => {
  const headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Allow-Methods": "POST, OPTIONS"
  };
  if (event.httpMethod === "OPTIONS") {
    return {
      statusCode: 200,
      headers,
      body: ""
    };
  }
  try {
    console.log("\u901A\u77E5\u9001\u4FE1\u30EA\u30AF\u30A8\u30B9\u30C8\u53D7\u4FE1:", event.body);
    if (event.httpMethod !== "POST") {
      return {
        statusCode: 405,
        headers,
        body: JSON.stringify({ error: "Method not allowed" })
      };
    }
    const { userId, notification } = JSON.parse(event.body);
    if (!userId || !notification) {
      return {
        statusCode: 400,
        headers,
        body: JSON.stringify({ error: "Missing required parameters" })
      };
    }
    console.log("\u901A\u77E5\u30C7\u30FC\u30BF:", { userId, notification });
    const { data: tokens, error } = await supabase.from("fcm_tokens").select("token").eq("user_id", userId).eq("is_admin", true);
    if (error) {
      console.error("\u30C8\u30FC\u30AF\u30F3\u53D6\u5F97\u30A8\u30E9\u30FC:", error);
      return {
        statusCode: 500,
        headers,
        body: JSON.stringify({ error: "Failed to get FCM tokens" })
      };
    }
    console.log("\u53D6\u5F97\u3055\u308C\u305F\u30C8\u30FC\u30AF\u30F3\u6570:", tokens ? tokens.length : 0);
    if (!tokens || tokens.length === 0) {
      return {
        statusCode: 404,
        headers,
        body: JSON.stringify({ error: "No admin tokens found" })
      };
    }
    const sendPromises = tokens.map(async ({ token }) => {
      try {
        console.log("\u30C8\u30FC\u30AF\u30F3\u306B\u901A\u77E5\u9001\u4FE1\u4E2D:", token.substring(0, 20) + "...");
        const message = {
          notification: {
            title: notification.title,
            body: notification.body
          },
          data: notification.data || {},
          token
        };
        const response = await admin.messaging().send(message);
        console.log("\u901A\u77E5\u9001\u4FE1\u6210\u529F:", response);
        return { success: true, token: token.substring(0, 10) + "..." };
      } catch (error2) {
        console.error("\u901A\u77E5\u9001\u4FE1\u30A8\u30E9\u30FC:", error2);
        return { success: false, token: token.substring(0, 10) + "...", error: error2.message };
      }
    });
    const results = await Promise.all(sendPromises);
    const successCount = results.filter((r) => r.success).length;
    console.log("\u901A\u77E5\u9001\u4FE1\u7D50\u679C:", { successCount, totalCount: tokens.length, results });
    return {
      statusCode: 200,
      headers,
      body: JSON.stringify({
        message: `\u901A\u77E5\u3092${successCount}\u4EF6\u9001\u4FE1\u3057\u307E\u3057\u305F`,
        results
      })
    };
  } catch (error) {
    console.error("\u95A2\u6570\u5B9F\u884C\u30A8\u30E9\u30FC:", error);
    return {
      statusCode: 500,
      headers,
      body: JSON.stringify({ error: "Internal server error" })
    };
  }
};
